\begin{theorem}[characterizations of variational convexity]\label{thm:coco env grad}
Suppose that $f:\mathbb{R}^n\to\overline{\mathbb{R}}$ is proper, lsc and prox-bounded
with threshold $\lambda_{f}>0$,
and that $f$ is prox-regular at $\bar x$ for $\bar v\in\partial f(\bar x)$.
%{\color{gray}
%Then for all $\lambda>0$ sufficiently small there exists an open convex neighborhood $U_{\lambda}$
%of $\bar{x}+\lambda \bar{v}$ on which the following are equivalent:
%}%
Then there exists \(0<\bar\lambda\leq \lambda_{f}\) such that $(\forall 0<\lambda<\bar{\lambda})\ P_{\lambda}f(\barx+\lambda\barv)=\barx$, and $\exists U_{\lambda}$
an open convex neighborhood of \(\bar x+\lambda\bar v\) for which the following equivalent properties hold:
	\begin{enumerate}
		\item\label{thm:coco env grad:: v cvx}
		$f$ is variationally convex at $\bar x$ for $\bar v$;
		\item\label{thm:coco env grad:: mono}
		\((\forall 0<\lambda<\bar\lambda)\)
		$\partial_p^\lambda f$ is monotone relative to $W_\lambda$;
% and $\bar v\in\partial_{p}^{\lambda}f(\bar x)$;
		\item\label{thmn:coco env grad:: max mono}
		\((\forall 0<\lambda<\bar\lambda)\)
		$\partial_p^\lambda f$ is maximally monotone relative to $W_\lambda$;
% and $\bar v\in\partial_{p}^{\lambda}f(\bar x)$;
		\item\label{thm:coco env grad:: firmly nonexap prox}
		\((\forall 0<\lambda<\bar\lambda)\)
		$P_\lambda f$ is firmly nonexpansive on $U_\lambda$;
		\item\label{thm:coco env grad:: averaged}
		\((\forall 0<\lambda<\bar\lambda)\) \((\exists0<\alpha<1)\)
		$P_\lambda f$ is $\alpha$-averaged on $U_\lambda$;
% and $P_{\lambda}f(\barx+\lambda\barv)=\barx$;
		\item\label{thm:coco env grad:: ne}
		\((\forall 0<\lambda<\bar\lambda)\)
		$P_\lambda f$ is nonexpansive on $U_\lambda$;
% and $P_{\lambda}f(\barx+\lambda\barv)=\barx$;
	%	\item\label{thm:coco env grad:: comono}
	%	\((\forall 0<\lambda<\bar\lambda)\) \((\exists0<\alpha<1)\)
	%	$\partial_p^\lambda f$ is $\rho$-monotone relative to \(W_\lambda\) with \(\rho=((2\alpha)^{-1}-1)\lambda^{-1}\);
		\item\label{envel:convex}
		\((\forall 0<\lambda<\bar\lambda)\)
		$e_\lambda f$ is convex on $U_\lambda$;
		\item\label{envel:convex spec}
		\((\exists0<\lambda<\bar \lambda)\)
		\(e_\lambda f\) is convex on $U_\lambda$;
		%($\partial_F\left(\lambda^{-1}j+f\right)$ is $1/\lambda$-strongly monotone
		%relative to $\Rn\times\left[ \lambda^{-1}U_\lambda\right]$.)
		\item\label{thm:coco env grad:: coco}
		\((\forall 0<\lambda<\bar\lambda)\)
		$\nabla e_\lambda f$ is $\lambda$-cocoercive on $U_\lambda$;
	\end{enumerate}
	\vspace*{-2mm}
		where $W_\lambda :=\{(x,v)\in\Rn\times\Rn|\ x+\lambda v\in U_\lambda\}$.
\end{theorem}

