\begin{fact}
%[resolvent representation of proximal mapping]
\label{fact: prox identity}
	\emph{\cite[Theorem 3.7]{wang23level}}
	Let $f:\Rn\to\overline{\R}$ be proper, lsc and prox-bounded with threshold
$\lambda_f>0$. Then
	\begin{equation}\label{prox and prox sub}
		(\forall 0<\lambda<\lambda_f)~P_\lambda  f =\big(\Id+\lambda\levp f\big)^{-1}.
	\end{equation}
Equivalently,
$ (\forall x\in\Rn)\ u\in P_{\lambda}f(x)\Leftrightarrow (u, \lambda^{-1}(x-u))\in\gph \partial_{p}^{\lambda}f$.
\begin{comment}
		Consequently, operator $\left(\Id+\lambda\levp f\right)^{-1}:\Rn\to2^{\Rn}$ has full domain, is compact-valued, and for every $x\in\Rn$
	\begin{align*}
		\left(\Id+\lambda\partial_p^\lambda f\right)^{-1}(x)=\big\{v\in\Rn:v_k\to v,\text{where }(\exists x_k\to x)(\exists \lambda_k\to\lambda)v_k\in\left(\Id+\lambda_k\partial_p^{\lambda_k} f\right)^{-1}(x_k)\big\}.
	\end{align*}
	Furthermore $\gph\levp f=T\left(\gph P_\lambda f\right)$, where
	$T=\begin{bmatrix}
		0&\Id\\\Id/\lambda&-\Id/\lambda
	\end{bmatrix}$ is an invertible linear transformation.
\end{comment}
\end{fact}

\begin{lemma}\label{l:minty} Let $U$ be a nonempty set in $\Rn$, let $\lambda>0$, and let
$W_{\lambda} :=\{(u,v)\in\Rn\times\Rn| \ u+\lambda v\in U\}.$
\begin{enumerate}
\item \label{i:operator}
Suppose that $A:\Rn\rightrightarrows\Rn$ and that $J_{\lambda A}$ is single-valued on $U$.
Then
\begin{equation}\label{e:mintylocal}
\gph A \cap W_{\lambda}=\{(J_{\lambda A}(x), \lambda^{-1}[x-J_{\lambda A}(x)])|\ x\in U\}.
\end{equation}
\item\label{i:function}
 Suppose that $f:\Rn\rightarrow\bR$ is proper, lsc and prox-bounded with threshold $\lambda_{f}$, and $0<\lambda<\lambda_{f}$. If $P_{\lambda}f$ is single-valued on $U$, then
 \begin{align}
 \gph \partial_{p}^{\lambda}f\cap W_{\lambda} &=\{(P_{\lambda}f(x), \lambda^{-1}[x-P_{\lambda}f(x)])|\ x\in U\}\label{e:proxf}\\
 & =\{(x-\lambda \nabla e_{\lambda}f(x),
    \nabla e_{\lambda}f(x))|\ x\in U\}.\label{e:gradf}
 \end{align}
\end{enumerate}
\end{lemma}

\begin{lemma}\label{lem:local coco Minty}
	Let $A:\Rn\rightrightarrows\Rn$ be a set-valued mapping, let $\lambda>0$, and
	let $\varnothing\neq U\subseteq\dom J_{\lambda A}$.
	Define $W_\lambda \coloneqq \{(u,v)\in\Rn\times\Rn|\ u+\lambda v\in U\}$.
	Then for \(\gamma>0\) the following are equivalent:
\begin{enumerate}
\item\label{i:resolvent:firm}
	$J_{\lambda A}$ is \(\gamma\)-cocoercive on $U$;
\item\label{i:monotone:hypo}
$A$ is \(\tfrac{1}{\lambda}\left(\gamma-1\right)\)-monotone relative to $W_\lambda$.
\end{enumerate}
