%		$J_{\lambda A}$ is \(\gamma\)-cocoercive on $U$;
%		\item\label{thm:local Minty::str mono}
%		$A$ is \(\tfrac{1}{\lambda}\left(\gamma-1\right)\)-comonotone relative to $W_\lambda$.
%	\end{enumerate}
\end{lemma}

